 root.append(section);if(g.providers?.length){const p=document.createElement('p');p.innerHTML='Szolgáltatók, akikhez már kapcsolódsz: '+g.providers.map(p=>`<a href="/foglalas?provider=${p.id}">${esc(p.name)}</a>`).join(' · ');root.prepend(p);}
